import { useState } from 'react'

function useTextStyles() {
  const [textStyles, setTextStyles] = useState({
    fontSize: 12,
    color: '#ffffff',
    bold: false,
    italic: false,
    underline: false,
    stroke: 'none',
    strokeColor: '#000000',
    strokeWidth: 2,
    backgroundColor: 'transparent',
    textAlign: 'left'
  })

  return [ textStyles, setTextStyles ]
}

export default useTextStyles
